import{_ as s,o as a,c as o,ag as n}from"./chunks/framework.DlQ8ZhpE.js";const h=JSON.parse('{"title":"Outbound IP Pool","description":"","frontmatter":{"title":"Outbound IP Pool","order":1},"headers":[],"relativePath":"docs/features/ip-pool.md","filePath":"en/docs/features/ip-pool.md"}'),t={name:"docs/features/ip-pool.md"};function p(r,e,i,l,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="outbound-ip-pool" tabindex="-1">Outbound IP Pool <a class="header-anchor" href="#outbound-ip-pool" aria-label="Permalink to &quot;Outbound IP Pool&quot;">​</a></h1><p>By default Pavonis uses the system outbound IP for all upstream requests. When you hold a large IPv6 address block (e.g. a <code>/48</code> subnet from HE Tunnel Broker), you can enable the <strong>IP pool</strong> to let Pavonis select an outbound IP from the pool according to a strategy, bypassing per-IP rate limits or access blocks imposed by upstream platforms.</p><p>The <code>random</code> strategy picks an outbound IP at random for each request, spreading requests across as many IPs as possible. The <code>ip_hash</code> strategy keeps the same client on the same outbound IP, which suits scenarios where the upstream needs to recognise the &quot;same user&quot; (e.g. APIs requiring session affinity). The global default strategy can be overridden per site.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>random: a random IP per request</span></span>
<span class="line"><span>  client A ─┬─ req 1 ──► 2001:db8::1a</span></span>
<span class="line"><span>            └─ req 2 ──► 2001:db8::7f</span></span>
<span class="line"><span>  client B ─── req 1 ──► 2001:db8::05</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ip_hash: fixed IP per client</span></span>
<span class="line"><span>  client A ─┬─ req 1 ──► 2001:db8::1a</span></span>
<span class="line"><span>            └─ req 2 ──► 2001:db8::1a</span></span>
<span class="line"><span>  client B ─── req 1 ──► 2001:db8::33</span></span></code></pre></div><p>See <a href="./../config/request#ippoolconfig-ip-pool"><code>IpPoolConfig</code></a> and the site-level <a href="./../config/sites"><code>ip_pool_strategy</code></a> for configuration.</p>`,5)])])}const b=s(t,[["render",p]]);export{h as __pageData,b as default};
